
local kmi=[==[]==]
local smolp=
(function(...)
local icuk={156,131,135,220,92,228,201,80,36,240,88,13,148,170,78,76,255,89,227,105,80,29,89,11,79,86,45,186,141}
local bzaje=bit32 or bit
local exruv=bzaje.bxor
for cl=1,#icuk do icuk[cl]=exruv(icuk[cl],(103*cl+117)%256) end
local va="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local qb={}
for ospyv=1,#va do qb[va:byte(ospyv)]=ospyv-1 end
local function puim(str)
  local R={} local acc,nb=0,0
  for oqgan=1,#str do
    local v=qb[str:byte(oqgan)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function gt(key,data)
  local S={} for wndes=0,255 do S[wndes]=wndes end
  local j=0
  for uadsz=0,255 do
    j=(j+S[uadsz]+key[(uadsz%#key)+1])%256
    S[uadsz],S[j]=S[j],S[uadsz]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(exruv(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=gt(icuk,puim(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local ei=nf()
return function(big) return ei(big) end
end)(...)

return smolp(kmi)
